<?php

namespace Database\Seeders;

use App\Models\FigureProfile;
use App\Models\PoseCatalog;
use Illuminate\Database\Seeder;
use RuntimeException;

/**
 * Loads the pose catalog generated by ai-service/catalog/build.py (shared/catalog/poses.json).
 * Keypoints there come from the same models as user photos, so both sides are directly comparable.
 * Poses missing from the file, or flagged as unusable for matching, are unpublished, not deleted:
 * favorites and past recommendations keep pointing at them.
 */
class PoseCatalogSeeder extends Seeder
{
    public function run(): void
    {
        $path = config('figurepose.catalog_path');
        if (! is_file($path)) {
            throw new RuntimeException("Pose catalog not found at [{$path}]. Set CATALOG_PATH.");
        }

        $catalog = json_decode((string) file_get_contents($path), true, flags: JSON_THROW_ON_ERROR);
        $profiles = FigureProfile::pluck('id', 'slug');
        $seen = [];

        foreach ($catalog['poses'] as $pose) {
            $profileId = $profiles[$pose['profile']] ?? throw new RuntimeException("Unknown profile [{$pose['profile']}] in catalog.");
            $seen[] = $pose['slug'];

            PoseCatalog::updateOrCreate(
                ['slug' => $pose['slug']],
                [
                    'figure_profile_id' => $profileId,
                    'name' => $pose['name'],
                    'category' => $pose['category'],
                    'difficulty' => $pose['difficulty'],
                    'description' => $pose['description'],
                    'joint_positions' => [
                        'image_size' => [$pose['image']['width'], $pose['image']['height']],
                        'keypoints' => $pose['keypoints'],
                        'joint_angles' => $pose['joint_angles'],
                        'orientation' => $pose['orientation'] ?? null,
                    ],
                    'constraints' => $pose['constraints'] ?: null,
                    'instructions' => $pose['instructions'],
                    'reference_image' => $pose['image']['path'],
                    'reference_credit' => $pose['credit'],
                    'is_published' => (bool) $pose['published'],
                ],
            );
        }

        PoseCatalog::whereNotIn('slug', $seen)->update(['is_published' => false]);
    }
}
